using System.Diagnostics;
using System.Text;
using System.Text.RegularExpressions;

namespace NCICParser.src;

/// <summary>
/// Parses the NCIC Code Manual text generated by
/// Poppler's pdftotext utility.
///
/// The parser discovers section groups, sections,
/// column definitions, parent-child relationships,
/// and code rows before performing several
/// normalization passes.
/// </summary>
internal class Parser
{
    /// <summary>
    /// Tracks the current segment parsing status
    /// </summary>
    private enum ParseState
    { 
        // Starting parsing at the section header
        InSectionHeader = 0,

        // Now expecting the code header (if any)
        ExpectCodeHeader = 1,

        // Now in the code list for parsing codes
        InCodeList = 2,
    }

    // These codes were found to be preceding prose text
    // and not another code, but were the last item in
    // their respective list, so they should signal done.
    private static readonly HashSet<string> knownDones = [
        "ZVI", 
        "X*"
    ];

    // These codes were found to have 2 blank lines between
    // them and the next code instead of just 1.
    private static readonly HashSet<string> blanksFollowing2 = [
        "EMULTIM", 
        "HBUFFER", 
        "DV0ICER"
    ];

    /// <summary>
    /// Entry point for parsing the text file containing the known
    /// NCIC codes
    /// </summary>
    /// <param name="filePath">Full file path to the NCIC text file (including extension)</param>
    /// <returns>List of Parsed SectionGroups containing all parsed content</returns>
    internal static List<SectionGroup> Parse(string filePath)
    {
        var dateEoPValue = "March 31, 2023";

        var lines = NCICFileReader.ReadFile(filePath);
        var returnValue = GetSectionGroups(lines);

        foreach (var grp in returnValue)
        {
            grp.Sections = GetSectionGroupSections(lines, grp);
            if (grp.Sections.Count == 0)
                continue;

            // Makes sure last sections in each group
            // stop before a new group begins (contains content)
            CloseSections(returnValue);

            foreach (var section in grp.Sections)
                section.CodeItemRows = ParseSection(lines, section, dateEoPValue);
        }

        CollapseGroups(returnValue);
        foreach (var group in returnValue)
        {
            CollapseSections(group.Sections);
            foreach (var section in group.Sections)
                CollapseCodeItemRows(section.CodeItemRows);
        }

        return returnValue;
    }

    /// <summary>
    /// Gets all the section groups
    /// </summary>
    /// <param name="lines">List of Raw Lines</param>
    /// <returns>List of SectionGroups</returns>
    private static List<SectionGroup> GetSectionGroups(List<RawLine> lines)
    {
        // Note: This *will* end up with adjacent duplicate groups, and
        // THAT'S OK, we'll compress them later in a post process.  This
        // way makes it much easier to process the file iteratively.
        List<SectionGroup> returnValue = [];
        List<RawLine> groupHeaderLines = [.. lines.Where(l => l.IsTableOfContents)];
        SectionGroup? lastSectionGroup = null;

        foreach (var tocLine in groupHeaderLines)
        {
            StringBuilder grpName = new();
            int idx = lines.IndexOf(tocLine);

            // Seek back to the FF to find the actual start line of the group name
            for (int i = idx - 1; i >= 0; i--)
            {
                if (grpName.Length > 0)
                    grpName.Insert(0, lines[i].Text.Trim() + " ");
                else
                    grpName.Append(lines[i].Text.Trim());

                if (lines[i].IsFormFeedLine)
                {
                    RawLine line = lines[i];
                    string temp = grpName.ToString();

                    SectionGroup newGroup = new(line, temp);
                    returnValue.Add(newGroup);

                    // Last Group (if any, ends with the start of this one)...
                    lastSectionGroup?.FileLineNumberEnd = newGroup.FileLineNumber - 1;
                    lastSectionGroup = newGroup;
                    break;
                }
            }
        }

        return returnValue;
    }

    /// <summary>
    /// Gets all sections for the specified SectionGroup
    /// </summary>
    /// <param name="lines">List of Raw Lines</param>
    /// <param name="group">Current SectionGroup</param>
    /// <returns>List of Sections for this group</returns>
    private static List<Section> GetSectionGroupSections(List<RawLine> lines, SectionGroup group)
    {
        // Note: This *will* end up with adjacent duplicate sections, and
        // THAT'S OK, we'll compress them later in a post process.  This
        // way makes it much easier to process the file interatively.

        List<Section> returnValue = [];
        Section? lastSection = null;

        // Get all the section start lines within this group...
        List<RawLine> sectionLines = [.. lines.Where(i => i.IsSectionHeader
                                                     && i.FileLineNumber > group.FileLineNumber
                                                     && (i.FileLineNumber <= group.FileLineNumberEnd
                                                        || group.FileLineNumberEnd == -1))];

        foreach (RawLine sectionLine in sectionLines)
        {
            // Only interested in building the section object,
            // NOT parsing the section content just yet...
            StringBuilder sectionName = new();
            for (int i = sectionLine.Index; i < lines.Count; i++)
            { 
                RawLine curLine = lines[i];
                if (curLine.IsBlank)
                {
                    var newSection = new Section(sectionLine, sectionName.ToString());
                    lastSection?.FileLineNumberEnd = newSection.FileLineNumber - 1;
                    returnValue.Add(newSection);
                    lastSection = newSection;

                    break;
                }
                else
                {
                    if (sectionName.Length > 0)
                        sectionName.Append(' ');

                    sectionName.Append(curLine.Text.Trim());
                }
            }
        }

        return returnValue;
    }

    /// <summary>
    /// Determines the last line of each section to encapsulate the
    /// parsing scope.
    /// </summary>
    /// <param name="groups">List of SectionGroups</param>
    private static void CloseSections(List<SectionGroup> groups)
    {
        for (var i = 0; i < groups.Count - 1; i++)
        {
            var grp = groups[i];
            if (grp.Sections.Count == 0)
                continue;

            grp.Sections[^1].FileLineNumberEnd = groups[i + 1].FileLineNumber - 1;
        }
    }

    /// <summary>
    /// Triggered when parsing a code list when the number of blank
    /// lines exceeds the threshold count (depending on last code)
    /// </summary>
    /// <param name="lines">List of RawLines</param>
    /// <param name="startLine">Index of the latest blank line encountered</param>
    /// <param name="lastCode">Last valid code processed before this occurrence</param>
    /// <returns>true if parsing is done, or false if not done</returns>
    private static bool IsDoneParsing(List<RawLine> lines, int startLine, string? lastCode)
    {
        if (lastCode is not null && knownDones.Contains(lastCode))
            return true;

        for (int i = startLine; i < lines.Count - 1; i++)
        { 
            RawLine line = lines[i];
            if (line.IsBlank)
                continue;
            else if (line.IsDateLine)   // Near bottom of every page...
                return true;
            else if (line.Text.Contains(':'))
                return true;            // A parent line is next..
            else                        // Some other non-blank to consider...
                return false;
        }

        return true;
    }

    /// <summary>
    /// Determines the blank line tolerance between code row items
    /// </summary>
    /// <param name="code">Current code to set from</param>
    /// <returns>Number of blank lines expected from current code to next</returns>
    private static int GetBlankTolerance(string code) =>
        blanksFollowing2.Contains(code)
         ? 2
         : 1;

    /// <summary>
    /// Parses the current section
    /// </summary>
    /// <param name="lines">List of RawLines</param>
    /// <param name="section">Current Section</param>
    /// <param name="dateEoPValue">Date on the bottom of each page</param>
    /// <returns>Fully parsed section content</returns>
    private static List<CodeItemRow> ParseSection(List<RawLine> lines, Section section, string dateEoPValue)
    {
        List<CodeItemRow> returnValue = [];
        List<RawLine> sectionLines = [.. lines.Where(i => i.FileLineNumber > section.FileLineNumber
                                                      && i.FileLineNumber <= section.FileLineNumberEnd)];

        // Since the section start contains the section name, we have to find the first blank to know 
        // we're past the name.
        string? lastValidCode = null;
        int blankTolerance = 2;
        var parent = "";
        var parseState = ParseState.InSectionHeader;
        var parsePattern = string.Empty;
        var blankCount = 0;

        foreach (var line in sectionLines)
        {
            //Debug.Print($"Page: {line.PageNumber}, FileLine: {line.FileLineNumber}, \"{line.Text}\"");

            // There's always a blank line following the header..
            if (parseState == ParseState.InSectionHeader && line.IsBlank)
            {
                parseState = ParseState.ExpectCodeHeader;
            }

            // Have we hit the bottom of a page?
            else if (line.Text == dateEoPValue)
            {
                break;
            }

            else if (parseState == ParseState.ExpectCodeHeader)
            {
                if (! line.IsBlank && line.IsCodeHeader)
                {
                    // Get our code headers...
                    section.CodeColumns = line.GetColumnSpecs();
                    parsePattern = section.GetCodeRegExPattern();
                    parseState = ParseState.InCodeList;
                    blankCount = 0;

                    // Set parent item (if any)...
                    RawLine parentLine = lines[line.Index - 1];
                    parent = parentLine.Text.Trim();
                }
            }
            
            else if (parseState == ParseState.InCodeList)
            {
                // Usually code sets are separated by multiple blank lines, 
                // while a code list will separate each code line by a single
                // blank line.. AGAIN this is usual, but not always, so depending
                // on the last code item, we'll set a tolerance and if hit,
                // check further to see if it's really done or an issue.
                if (line.IsBlank)
                {
                    if (++blankCount > blankTolerance)
                    {
                        // Determine if we're actually done (nothing but empty page following up to the date line...)
                        if (!IsDoneParsing(lines, line.Index, lastValidCode))
                        {
                            Debug.WriteLine(
                                 $"Blank Tolerance Hit | " +
                                 $"Section: {section.Name} | " +
                                 $"Page: {line.PageNumber} | " +
                                 $"Page Line: {line.PageLineNumber} | " +
                                 $"File Line: {line.FileLineNumber} | " +
                                 $"Last Code: '{lastValidCode}'"
                             );
                        }
                        
                        // Otherwise, just reset...
                        parseState = ParseState.ExpectCodeHeader;
                        blankCount = 0;
                    }
                }
                else
                {
                    // Parse the current row...
                    CodeItemRow row = ParseRow(line, parent, parsePattern);

                    if (row.CodeItemValues[0].Length > 0)
                    { 
                        lastValidCode = row.CodeItemValues[0];
                        blankTolerance = GetBlankTolerance(lastValidCode);
                    }
                    returnValue.Add(row);

                    // Reset blank counter
                    blankCount = 0;
                }
            }
            
            else
            {
                // Nothing we want to do here...
            }
        }

        return returnValue;
    }

    /// <summary>
    /// Parses the current code row
    /// </summary>
    /// <param name="line">Current RawLine</param>
    /// <param name="parent">Parent code (if any)</param>
    /// <param name="pattern">Regex Pattern used to parse</param>
    /// <returns>CodeItemRow containing code content for this line</returns>
    private static CodeItemRow ParseRow(RawLine line, string parent, string pattern)
    {
        // Make sure the text is wide enough for the pattern to handle as fixed width.
        string text = line.Text.PadRight(255);

        Match match = Regex.Match(text, pattern);

        CodeItemRow returnValue = new(line)
        {
            Rejected = !match.Success,
            ParentCodeRaw = parent
        };

        if (match.Success)
        {
            for (int i = 1; i < match.Groups.Count; i++)
            {
                returnValue.CodeItemValues.Add(match.Groups[i].Value.Trim());
            }
        }

        return returnValue;
    }

    /// <summary>
    /// Collapses duplicated groups into the first occurrence. 
    /// </summary>
    /// <param name="groups">List of SectionGroups</param>
    private static void CollapseGroups(List<SectionGroup> groups)
    {
        int idx = 0;
        while (idx < groups.Count - 1)
        {
            SectionGroup root = groups[idx];
            SectionGroup test = groups[idx + 1];

            if (root.Name == test.Name)
            {
                root.Sections.AddRange(test.Sections);
                root.FileLineNumberEnd = test.FileLineNumberEnd;
                groups.Remove(test);
            }
            else if (root.Sections.Count == 0)
                groups.Remove(root);
            else
                idx++;
        }
    }

    /// <summary>
    /// Collapses duplicated segments into the first occurrence
    /// </summary>
    /// <param name="sections">List of Sections</param>
    private static void CollapseSections(List<Section> sections)
    {
        int idx = 0;
        while (idx < sections.Count - 1)
        {
            Section root = sections[idx];
            Section test = sections[idx + 1];

            if (root.Name == test.Name)
            {
                root.CodeItemRows.AddRange(test.CodeItemRows);
                root.FileLineNumberEnd = test.FileLineNumberEnd;
                sections.Remove(test);
            }
            else if (root.CodeItemRows.Count == 0)
                sections.Remove(root);
            else
                idx++;
        }
    }

    /// <summary>
    /// Collapses extended code item rows into a single row
    /// </summary>
    /// <param name="rows">List of CodeItemRows</param>
    private static void CollapseCodeItemRows(List<CodeItemRow> rows)
    {
        int idx = 0;
        while (idx < rows.Count - 1)
        {
            CodeItemRow test = rows[idx + 1];

            // No code means it was a row of additional values
            // from a previous row.
            if (test.CodeItemValues[0].Length == 0)
            {
                CodeItemRow root = rows[idx];

                for (var i = 0; i < test.CodeItemValues.Count; i++)
                    if (test.CodeItemValues[i].Length > 0)
                        root.CodeItemValues[i] += " " + test.CodeItemValues[i];

                rows.Remove(test);
            }
            else
                idx++;
        }
    }

}
